#' Plot Skynet
#'
#' Creates OD maps from make.net functions. Routes are drawn as great
#' circles, with line width and opacity scaled by passengers, and airports
#' sized by traffic. By default a static ggplot2 map is returned; with
#' \code{interactive = TRUE} a zoomable leaflet map is returned instead.
#'
#' @param x Skynet Object
#' (generated by make_net_dir,make_net_und or make_net_path)
#' @param pct percentage of edges to include (busiest routes first)
#' @param interactive returns a leaflet map instead of a ggplot2 map
#' @param crs projection used for the static map (any value accepted by
#' \code{sf::st_crs}). By default an Albers equal area projection is used for
#' North American networks and Equal Earth for everything else.
#' Requires the sf package; without it a simple lat/long map is drawn.
#' @param carriers maximum number of carriers shown individually when the
#' network is grouped by carrier. Remaining carriers are grouped as "Other".
#'
#' @examples
#' \dontrun{
#' network <- make_net_dir(OD_Sample)
#' net_map(network, pct = 10)
#' net_map(network, pct = 10, interactive = TRUE)
#' }
#'
# Import to avoid R CMD check NOTE
# skynet > ggplot2::annotation_borders() > ggplot2::map_data() > maps::map()
#' @importFrom maps map
#' @export
#'

net_map <- function(x, pct = 60, interactive = FALSE, crs = NULL,
                    carriers = 8){

  x <- x[[2]] %>%
    ungroup() %>%
    filter(origin != dest)

  if(nchar(x[[1]][1]) == 5){
    # Metro option
    if(is.null(x[["passengers"]])){
      x <- rename(x, passengers = weight)
    }
    airports <- select(MetroLookup, origin, latitude, longitude)
    nodes <- x %>%
      nodeStatsMetro() %>%
      rename(origin = airport) %>%
      mutate(description = sub(" \\(Metropolitan Area\\)", "",
                               as.character(description)))

    }else{
      airports <- select(airportCode, origin, latitude, longitude)
      nodes <- x %>%
        node_stats() %>%
        select(airport, latitude, longitude, freq) %>%
        rename(origin = airport) %>%
        mutate(description = origin)
      }
  #-----------------------------------------------------


  # Merges flights and airport data for Latitude/Longitude info

  flights <- merge(x, airports, by = "origin")
  if(!is.null(x[["op_carrier"]])){
    flights <- select(flights, origin, dest,
                      passengers, latitude, longitude, op_carrier)
  }else{
    flights <- select(flights, origin, dest,
                      passengers, latitude, longitude)
  }
  flights <- merge(flights, airports, by.x = "dest", by.y = "origin")

  # Keeps busiest routes only
  flights <- flights %>%
    filter(!is.na(latitude.x), !is.na(latitude.y)) %>%
    filter(passengers >= quantile(passengers, prob = 1-(pct/100))) %>%
    arrange(passengers)

  flights$id <- 1:nrow(flights)

  # Groups smaller carriers as "Other"
  if(!is.null(flights[["op_carrier"]])){
    top <- flights %>%
      group_by(op_carrier) %>%
      summarise(passengers = sum(passengers)) %>%
      arrange(-passengers)
    top <- head(top$op_carrier, carriers)

    flights <- flights %>%
      mutate(op_carrier = ifelse(op_carrier %in% top, op_carrier, "Other"))

    carrier_levels <- c(top, "Other")
    carrier_levels <- carrier_levels[carrier_levels %in% flights$op_carrier]
    flights$op_carrier <- factor(flights$op_carrier, levels = carrier_levels)

    # Okabe-Ito colors, grey for "Other"
    cols <- c("#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00",
              "#56B4E9", "#882255", "#999933", "#332288", "#44AA99")
    cols <- rep(cols, length.out = length(carrier_levels))
    cols[carrier_levels == "Other"] <- "grey70"
    names(cols) <- carrier_levels
  }

  # Only airports served by the plotted routes
  nodes <- nodes %>%
    filter(origin %in% c(flights$origin, flights$dest), !is.na(latitude))

  #-----------------------------------------------------


  # Creates great circle paths, one data frame per route

  arcs <- list()
  for(i in 1:nrow(flights)){
    arc <- gcIntermediate(c(flights$longitude.x[i], flights$latitude.x[i]),
                          c(flights$longitude.y[i], flights$latitude.y[i]),
                          n = 50, addStartEnd = TRUE, breakAtDateLine = TRUE)

    # Routes crossing the date line come in two parts
    if(is.list(arc) == FALSE){
      arc <- list(arc)
    }
    for(j in 1:length(arc)){
      arcs[[paste(i, "_", j, sep = "")]] <- data.frame(
        lon = arc[[j]][, 1], lat = arc[[j]][, 2],
        id = i, group = paste(i, "_", j, sep = ""))
    }
  }

  arcs <- do.call(rbind, arcs) %>%
    left_join(select(flights, -latitude.x, -longitude.x,
                     -latitude.y, -longitude.y), by = "id")

  #-----------------------------------------------------

  if(interactive == TRUE){
    if(is.null(flights[["op_carrier"]])){
      cols <- c(all = "royalblue")
      arcs$col <- "all"
    }else{
      arcs$col <- as.character(arcs$op_carrier)
    }
    return(do.call(netMapLeaflet, list(arcs, nodes, cols)))
  }

  #-----------------------------------------------------


  # Create World and Plot Map

  worldmap <- annotation_borders("world", colour = "white", fill = "grey90",
                                 linewidth = .2) # create a layer of borders

  # Chooses color for carriers when present

  if(is.null(flights[["op_carrier"]])){
    gcurve <- geom_path(data = arcs,
                        aes(x = lon, y = lat, group = group,
                            linewidth = passengers, alpha = passengers),
                        color = "royalblue", lineend = "round")
    gcolor <- NULL
  }else{
    gcurve <- geom_path(data = arcs,
                        aes(x = lon, y = lat, group = group,
                            linewidth = passengers, alpha = passengers,
                            col = op_carrier),
                        lineend = "round")
    gcolor <- scale_colour_manual(name = "Carrier", values = cols,
                                  guide = guide_legend(override.aes = list(
                                    linewidth = 1.5, alpha = 1)))
  }

  #-----------------------------------------------------


  # Chooses projection and limits from the plotted airports

  xlim <- range(nodes$longitude) + c(-3, 3)
  ylim <- range(nodes$latitude) + c(-2, 2)

  if(requireNamespace("sf", quietly = TRUE) == FALSE){
    gcoord <- coord_quickmap(xlim = xlim, ylim = ylim)
  }else{
    if(is.null(crs)){
      if(all(nodes$longitude < -50 & nodes$latitude > 0)){
        # North America
        crs <- paste("+proj=aea +lat_1=29.5 +lat_2=45.5 +lat_0=37.5",
                     "+lon_0=-96 +datum=WGS84 +units=m")
      }else{
        crs <- "+proj=eqearth +lon_0=0 +datum=WGS84 +units=m"
      }
    }
    gcoord <- coord_sf(crs = crs, default_crs = 4326, xlim = xlim,
                       ylim = ylim, expand = FALSE, datum = NA,
                       lims_method = "box")
  }

  #-----------------------------------------------------

  p <- ggplot() + worldmap + gcurve + gcolor +
    scale_linewidth_continuous(range = c(.15, 1.6), guide = "none") +
    scale_alpha_continuous(range = c(.25, .85), guide = "none") +
    geom_point(data = nodes,
               aes(x = longitude, y = latitude, size = freq),
               col = "grey20", alpha = .7, stroke = 0) +
    scale_size_area(max_size = 2.5, guide = "none") +
    ggrepel::geom_text_repel(data = nodes[nodes$freq >= quantile(nodes$freq,
                                                                 prob = 1-4/100),],
                             aes(x = longitude, y = latitude,
                                 label = description),
                             col = "black", size = 2.4,
                             bg.color = "white", bg.r = .12,
                             segment.color = NA, fontface = "bold",
                             max.overlaps = Inf) +
    gcoord +
    theme(panel.background = element_rect(fill = "white", colour = NA),
          panel.grid = element_blank(),
          axis.line = element_blank(),
          axis.text.x = element_blank(),
          axis.text.y = element_blank(),
          axis.ticks = element_blank(),
          axis.title.x = element_blank(),
          axis.title.y = element_blank(),
          legend.key = element_blank(),
          legend.position = "bottom",
          legend.title.position = "top")

  return(p)

}


# Interactive leaflet map
netMapLeaflet <- function(arcs, nodes, cols){

  # Line width from 0.5 to 5 based on passengers
  arcs$weight <- .5 + 4.5*(arcs$passengers - min(arcs$passengers))/
    max(max(arcs$passengers) - min(arcs$passengers), 1)

  m <- leaflet() %>%
    addProviderTiles("CartoDB.Positron")

  for(g in unique(arcs$group)){
    arc <- arcs[arcs$group == g, ]
    m <- m %>%
      addPolylines(lng = arc$lon, lat = arc$lat,
                   color = cols[[arc$col[1]]], weight = arc$weight[1],
                   opacity = .6,
                   label = paste(arc$origin[1], " - ", arc$dest[1], ": ",
                                 format(arc$passengers[1], big.mark = ","),
                                 " passengers", sep = ""),
                   highlightOptions = highlightOptions(weight = 6,
                                                       opacity = 1,
                                                       bringToFront = TRUE))
  }

  m <- m %>%
    addCircleMarkers(lng = nodes$longitude, lat = nodes$latitude,
                     radius = 2 + 8*sqrt(nodes$freq/max(nodes$freq)),
                     color = "grey20", weight = 1, fillOpacity = .6,
                     label = paste(nodes$description, ": ",
                                   format(nodes$freq, big.mark = ","),
                                   " passengers", sep = ""))

  if(!is.null(arcs[["op_carrier"]])){
    m <- m %>%
      addLegend("bottomright", colors = unname(cols), labels = names(cols),
                title = "Carrier", opacity = 1)
  }

  return(m)

}

netMap <- function(...){
  warning(paste("netMap is deprecated, use net_map(), instead."))
  do.call(net_map, list(...))
}

globalVariables(c("latitude", "longitude", "latitude.x", "longitude.x",
                  "latitude.y", "longitude.y", "gcurve", "airport",
                  "lon", "lat", "group", "op_carrier", "description",
                  "weight", "id"))
